/* Local primitives, bounded learning and physical affordances. No house/city/war action or blueprint. */
import {hash,completeGenome} from './genetics.js';
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
export const MATERIALS=[
 {name:'Madera',color:'#b7a07b',rigidity:.7,insulation:.75,mass:.6,decay:.00014},
 {name:'Piedra',color:'#9baaaa',rigidity:1,insulation:.3,mass:1,decay:0},
 {name:'Fibra',color:'#c6ca91',rigidity:.2,insulation:1,mass:.2,decay:.00028},
 {name:'Arcilla',color:'#bd937c',rigidity:.55,insulation:.6,mass:.7,decay:.00007}
];
export const ACTIONS=['observe','gather','place','rest','share','explore','contest'];
export const ACTION_NAMES={observe:'Observar',gather:'Recoger',place:'Colocar / unir',rest:'Buscar refugio',share:'Compartir',explore:'Explorar',contest:'Disputar'};
export function mind(c,mother,father){completeGenome(c.dna);if(c.pregnancy?.fatherDna)completeGenome(c.pregnancy.fatherDna);c.mind??={q:{},visits:{},trials:0,successes:0,learnedFrom:0,home:{x:c.x,z:c.z},memory:[],trust:{},carrying:null,job:null,clock:0,lastAction:null,pendingReward:null,placed:0,shared:0,contests:0};const m=c.mind;if(mother?.mind&&father?.mind&&!m.culturalParent){for(const parent of [mother,father])for(const [key,val] of Object.entries(parent.mind.q))m.q[key]=(m.q[key]||0)+val*.2;m.culturalParent=true;m.learnedFrom=2;}return m;}
export class Culture{
 constructor(sim,saved){this.sim=sim;this.materials=saved?.materials||[];this.blocks=saved?.blocks||[];this.trails=saved?.trails||[];this.nextId=saved?.nextId||1;this.clock=0;this.expansionPressure=saved?.expansionPressure||0;this.lastExpansion=saved?.lastExpansion??sim.time;this.discovered=saved?.discovered||0;this.totals=saved?.totals||{collected:0,placed:0,shared:0,contests:0,learned:0};this.groups=[];this.revision=1;this.blockGrid=new Map();this.materialById=new Map();this.nextGroupNotice=sim.time+30;
 if(!saved){for(let i=0;i<200;i++)this.spawnMaterial(sim.point(),i%4,3);}for(const c of [...sim.creatures,...sim.archive])mind(c);this.index();}
 spawnMaterial(p,type,quantity=1){if(this.materials.length>=420){const same=this.materials.find(m=>m.type===type);if(same)same.quantity+=quantity;return same||null;}const r={id:this.nextId++,x:p.x,z:p.z,type,quantity};this.materials.push(r);this.materialById?.set(r.id,r);this.revision++;return r;}
 index(){this.blockGrid.clear();for(const b of this.blocks){const key=Math.round(b.x/.8)+','+Math.round(b.z/.8);let ar=this.blockGrid.get(key);if(!ar){ar=[];this.blockGrid.set(key,ar);}ar.push(b);}this.materialById.clear();for(const m of this.materials)this.materialById.set(m.id,m);}
 nearBlocks(x,z,r=3){const result=[];for(let ix=Math.floor((x-r)/.8);ix<=Math.ceil((x+r)/.8);ix++)for(let iz=Math.floor((z-r)/.8);iz<=Math.ceil((z+r)/.8);iz++){const bucket=this.blockGrid.get(ix+','+iz);if(bucket)for(const b of bucket)if(Math.abs(b.x-x)<r&&Math.abs(b.z-z)<r)result.push(b);}return result;}
 shelter(x,z){const blocks=this.nearBlocks(x,z,2);let value=0;const sectors=new Set();for(const b of blocks){const d=Math.hypot(b.x-x,b.z-z);if(d<.35)continue;sectors.add(Math.floor((Math.atan2(b.z-z,b.x-x)+Math.PI)/(.5*Math.PI)));value+=MATERIALS[b.type].insulation*.1*(1+b.level*.2);}return clamp(value*(.5+sectors.size*.2),0,.8);}
 blocked(x,z){const a=this.blockGrid.get(Math.round(x/.8)+','+Math.round(z/.8));return a?.some(b=>b.level===0&&MATERIALS[b.type].rigidity>.5)||false;}
 reward(c,action,context,value){const m=c.mind,key=context+':'+action,alpha=.08+c.dna.traits.plasticity*.10;m.q[key]=(m.q[key]||0)+alpha*(clamp(value,-3,3)-(m.q[key]||0));m.visits[key]=(m.visits[key]||0)+1;m.trials++;if(value>0)m.successes++;this.totals.learned++;}
 context(c){return(c.energy<55?'hungry':this.sim.rain>0||this.sim.climate.temperature<14?'exposed':'calm');}
 utility(c){return c.energy*.03+c.health*.02+this.shelter(c.x,c.z)*(.5+(this.sim.rain>0?2:0));}
 sense(c){const radius=3+c.dna.traits.cognition*5;let closest=null,best=radius;for(const m of this.materials){if(!this.sim.valid(m.x,m.z,c.species))continue;const d=Math.hypot(m.x-c.x,m.z-c.z);if(d<best){closest=m;best=d;}}const peers=[];for(const o of this.sim.creatures)if(o!==c&&Math.hypot(o.x-c.x,o.z-c.z)<radius)peers.push(o);return{material:closest,peers,blocks:this.nearBlocks(c.x,c.z,radius)};}
 choose(c){const m=c.mind||mind(c),g=c.dna.traits,sense=this.sense(c),ctx=this.context(c);if(c.energy<38||c.age<2||c.stage||c.pregnancy?.remaining<4)return false;if(this.sim.random()>.30+g.curiosity*.13)return false;
 if(m.pendingReward){this.reward(c,m.pendingReward.action,m.pendingReward.context,this.utility(c)-m.pendingReward.before);m.pendingReward=null;}
 const available=['observe','explore'];if(sense.material&&!m.carrying)available.push('gather');if(m.carrying)available.push('place');if(sense.blocks.length)available.push('rest');if(c.energy>65&&sense.peers.some(o=>o.energy<55))available.push('share');if(g.assertion>.6&&sense.peers.some(o=>o.mind?.carrying)&&c.energy<76)available.push('contest');let action=available[0],score=-Infinity;
 // Contextual bandit: utility estimates, curiosity and observed consequences, not a civilization tech tree.
 for(const a of available){const key=ctx+':'+a,visits=m.visits[key]||0,explore=g.curiosity*Math.sqrt(1/(1+visits));let prior=a==='gather'?.2:a==='place'?.25:a==='rest'&&ctx==='exposed'?.45:a==='share'?g.sociality*.15:a==='contest'?g.assertion*.10:0;const val=(m.q[key]||0)+explore+prior+this.sim.random()*.45;if(val>score){score=val;action=a;}}
 m.lastAction=action;m.clock=5;m.pendingReward={action,context:ctx,before:this.utility(c)};const radius=3+g.cognition*4;
 if(action==='observe'){const better=sense.peers.filter(o=>o.mind?.successes>m.successes).sort((a,b)=>b.mind.successes-a.mind.successes)[0];if(better&&g.sociality>.3){const entries=Object.entries(better.mind.q).sort((a,b)=>b[1]-a[1]);for(const [key,val]of entries.slice(0,1+Math.floor(g.cognition*2)))m.q[key]=(m.q[key]||0)*.8+val*.2;m.learnedFrom++;}c.state='Observando';c.target=null;c.think=2;return true;}
 if(action==='gather'){m.job={action,id:sense.material.id,x:sense.material.x,z:sense.material.z,until:this.sim.time+20};c.target={x:m.job.x,z:m.job.z,kind:'culture'};c.state='Recolectando';return true;}
 if(action==='place'){const candidates=[];const hx=m.home.x,hz=m.home.z;for(let i=0;i<3+Math.floor(g.cognition*5);i++){const angle=this.sim.random()*6.28,rr=1.2+this.sim.random()*2.5;const x=Math.round((hx+Math.sin(angle)*rr)/.8)*.8,z=Math.round((hz+Math.cos(angle)*rr)/.8)*.8;if(!this.sim.valid(x,z,c.species))continue;const same=this.blockGrid.get(Math.round(x/.8)+','+Math.round(z/.8))||[],level=same.length?Math.max(...same.map(b=>b.level))+1:0;if(level>2+Math.floor(g.dexterity)||level>0&&!same.some(b=>MATERIALS[b.type].rigidity>=.5))continue;const neighbors=this.nearBlocks(x,z,1.1).length;const people=sense.peers.filter(o=>Math.hypot(o.x-x,o.z-z)<.7).length;if(people)continue;const material=MATERIALS[m.carrying.type],value=neighbors*.20+material.insulation*(this.sim.rain>0?.8:.35)-level*.10-this.sim.random()*.35;candidates.push({x,z,level,value});}if(!candidates.length){this.drop(c);return false;}candidates.sort((a,b)=>b.value-a.value);const dest=candidates[0];m.job={action,...dest,until:this.sim.time+24};c.target={x:dest.x,z:dest.z,kind:'culture'};c.state='Transportando';return true;}
 if(action==='rest'){let best={x:c.x,z:c.z,value:this.shelter(c.x,c.z)};for(const b of sense.blocks.slice(0,Math.ceil(g.cognition*6))){const x=b.x+.9,z=b.z+.9;if(!this.sim.valid(x,z,c.species)||this.blocked(x,z))continue;const value=this.shelter(x,z);if(value>best.value)best={x,z,value};}m.home={x:best.x,z:best.z};m.job={action,x:best.x,z:best.z,until:this.sim.time+20};c.target={x:best.x,z:best.z,kind:'culture'};c.state='Buscando cobijo';return true;}
 if(action==='share'){const peer=sense.peers.filter(o=>o.energy<55).sort((a,b)=>a.energy-b.energy)[0];m.job={action,id:peer.id,x:peer.x,z:peer.z,until:this.sim.time+15};c.target={x:peer.x,z:peer.z,kind:'culture'};c.state='Acercando alimento';return true;}
 if(action==='contest'){const peer=sense.peers.find(o=>o.mind?.carrying&&o.id!==c.id);m.job={action,id:peer.id,x:peer.x,z:peer.z,until:this.sim.time+12};c.target={x:peer.x,z:peer.z,kind:'culture'};c.state='Disputando un recurso';return true;}
 // Curiosity is oriented away from familiar locations; crowded/hungry frontier visits create discovery pressure.
 const angle=this.sim.random()*6.28,x=c.x+Math.sin(angle)*radius*1.6,z=c.z+Math.cos(angle)*radius*1.6;if(this.sim.valid(x,z,c.species)){m.job={action,x,z,until:this.sim.time+24};c.target={x,z,kind:'culture'};c.state='Explorando lo desconocido';return true;}if(Math.hypot(c.x,c.z)>this.sim.radius-5&&g.curiosity>.5){this.expansionPressure+=g.curiosity;this.discovered++;}return false;
 }
 drop(c){const m=c.mind;if(!m?.carrying)return;this.spawnMaterial({x:c.x,z:c.z},m.carrying.type,1);m.carrying=null;m.job=null;}
 updateAgent(c,dt){const m=c.mind||mind(c);m.clock=Math.max(0,m.clock-dt);c.shelter=this.shelter(c.x,c.z);c.energy-=dt*.025*c.dna.traits.cognition;c.energy+=dt*c.shelter*(this.sim.rain>0?.17:.065);c.energy=clamp(c.energy,-20,100);
 if(c.stage||c.state==='Huyendo'||c.energy<30){m.job=null;return false;}if(!m.job)return false;const j=m.job;if(this.sim.time>j.until){this.reward(c,j.action,this.context(c),-.2);m.job=null;c.think=0;return false;}
 if(j.action==='share'||j.action==='contest'){const peer=this.sim.byId.get(j.id);if(!peer){m.job=null;return false;}j.x=peer.x;j.z=peer.z;}
 c.target={x:j.x,z:j.z,kind:'culture'};c.think=1;const distance=Math.hypot(c.x-j.x,c.z-j.z);if(distance>1.15)return false;let benefit=0;const ctx=this.context(c);
 if(j.action==='gather'){const r=this.materialById.get(j.id);if(r&&r.quantity>0&&!m.carrying){const material=MATERIALS[r.type];if(material.mass>c.dna.traits.dexterity+.25){benefit=-.3;}else{m.carrying={type:r.type};r.quantity--;if(r.quantity===0){this.materials.splice(this.materials.indexOf(r),1);this.materialById.delete(r.id);}this.totals.collected++;c.energy-=.6;benefit=.08;this.revision++;}}c.state='Examinando un material';}
 if(j.action==='place'&&m.carrying){if(this.blocks.length<1400){const a=this.blockGrid.get(Math.round(j.x/.8)+','+Math.round(j.z/.8))||[];const level=a.length?Math.max(...a.map(b=>b.level))+1:0;if(level<4){const material=MATERIALS[m.carrying.type],b={id:this.nextId++,x:j.x,z:j.z,level,type:m.carrying.type,owner:c.id,family:c.species,health:1,born:this.sim.time};this.blocks.push(b);this.index();m.carrying=null;m.placed++;this.totals.placed++;c.energy-=.7;benefit=this.shelter(m.home.x,m.home.z)*.7-.02;this.revision++;}}c.state='Uniendo materiales';}
 if(j.action==='rest'){c.energy=Math.min(100,c.energy+this.shelter(c.x,c.z)*2);benefit=this.shelter(c.x,c.z);c.state='Descansando al abrigo';}
 if(j.action==='share'){const peer=this.sim.byId.get(j.id);if(peer&&c.energy>50){const quantity=Math.min(6,(100-peer.energy));peer.energy+=quantity;c.energy-=quantity*.9;peer.mind.trust[c.id]=(peer.mind.trust[c.id]||0)+1;m.trust[peer.id]=(m.trust[peer.id]||0)+.5;this.totals.shared++;m.shared++;benefit=c.dna.traits.sociality*.15;this.mark(c.x,c.z,c.species,'shared');}c.state='Compartiendo';}
 if(j.action==='contest'){const peer=this.sim.byId.get(j.id);if(peer?.mind.carrying&&peer.health>8){const allies=this.sim.creatures.filter(o=>o.id!==c.id&&o.id!==peer.id&&Math.hypot(o.x-peer.x,o.z-peer.z)<3&&(o.mind?.trust[peer.id]||0)>0).length;const injury=2+c.dna.traits.assertion*2;peer.health-=injury;c.health-=1+allies*2;c.energy-=2;peer.mind.trust[c.id]=-3;m.contests++;this.totals.contests++;this.mark(c.x,c.z,c.species,'alarm');if(this.sim.random()<.4&&!m.carrying){m.carrying=peer.mind.carrying;peer.mind.carrying=null;benefit=.1;}else benefit=-.25;if(this.totals.contests%5===1)this.sim.log('Una disputa por materiales provoca ayuda y represalias locales.','⚑','conflict',peer.id);}c.state='Enfrentándose';}
 if(j.action==='explore'){const novel=!m.memory.some(p=>Math.hypot(p.x-c.x,p.z-c.z)<3);if(novel){m.memory.push({x:c.x,z:c.z});m.memory=m.memory.slice(-Math.ceil(c.dna.traits.cognition*12));benefit=.1*c.dna.traits.curiosity;this.discovered++;}if(Math.hypot(c.x,c.z)>this.sim.radius-5&&(c.energy<70||this.sim.creatures.length>this.sim.capacity*.6))this.expansionPressure+=c.dna.traits.curiosity;this.mark(c.x,c.z,c.species,'trail');}
 this.reward(c,j.action,ctx,benefit);m.pendingReward={action:j.action,context:ctx,before:this.utility(c)};m.job=null;m.clock=2+this.sim.random()*3;c.target=null;c.think=1.6;return true;
 }
 mark(x,z,family,type){let t=this.trails.find(t=>t.family===family&&Math.hypot(t.x-x,t.z-z)<2);if(t){t.strength=Math.min(6,t.strength+1);t.type=type;}else this.trails.push({x,z,family,type,strength:1});this.trails=this.trails.slice(-180);}
 tick(dt){this.clock+=dt;if(this.clock<2)return;const elapsed=this.clock;this.clock=0;let changed=false;for(let i=this.blocks.length-1;i>=0;i--){const b=this.blocks[i],mat=MATERIALS[b.type];b.health-=elapsed*mat.decay*(this.sim.rain>0?3:1);if(b.health<=0){if(mat.decay)this.sim.deposit(b.x,b.z,1,mat.name);else this.spawnMaterial(b,b.type);this.blocks.splice(i,1);changed=true;}}
 if(changed){this.index();this.revision++;}for(const t of this.trails)t.strength-=elapsed*.006;this.trails=this.trails.filter(t=>t.strength>0);
 // Connected deposits are classified after construction, never used to schedule a city or a war.
 const groups=[],seen=new Set();for(const seed of this.blocks){if(seen.has(seed.id))continue;const group={id:seed.id,x:0,z:0,blocks:0,members:0,protection:0,maxLevel:0},todo=[seed];seen.add(seed.id);while(todo.length){const b=todo.pop();group.x+=b.x;group.z+=b.z;group.blocks++;group.maxLevel=Math.max(group.maxLevel,b.level);for(const o of this.nearBlocks(b.x,b.z,1.2))if(!seen.has(o.id)){seen.add(o.id);todo.push(o);}}if(group.blocks>=4){group.x/=group.blocks;group.z/=group.blocks;group.members=this.sim.creatures.filter(c=>Math.hypot(c.mind.home.x-group.x,c.mind.home.z-group.z)<6).length;group.protection=this.shelter(group.x,group.z);groups.push(group);}}this.groups=groups.sort((a,b)=>b.blocks-a.blocks).slice(0,30);
 if(this.groups.some(g=>g.blocks>=12&&g.members>=3)&&this.sim.time>this.nextGroupNotice){this.nextGroupNotice=this.sim.time+180;this.sim.log('Varios habitantes frecuentan una agrupación de materiales.','⌂','collective');}
 if(this.expansionPressure>12&&this.sim.time-this.lastExpansion>90){if(this.sim.expansions<3){this.sim.expand();this.lastExpansion=this.sim.time;this.expansionPressure=0;for(let i=0;i<55;i++)this.spawnMaterial(this.sim.point(),i%4,3);this.sim.log('La exploración de la frontera descubre más terreno y materiales.','↗','discovery');}else this.expansionPressure=12;}
 }
 snapshot(){return{materials:this.materials,blocks:this.blocks,trails:this.trails,nextId:this.nextId,expansionPressure:this.expansionPressure,lastExpansion:this.lastExpansion,discovered:this.discovered,totals:this.totals};}
}
